SELECT CASE WHEN credit_limit >= 16100 THEN 'high' WHEN credit_limit >= 7300 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, country, ROUND((100 * SUM(CASE WHEN segment = 'Consumer' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_consumer, MAX(credit_limit) AS max_credit_limit FROM customers WHERE LENGTH(email) >= 12 AND NOT is_active GROUP BY credit_limit_bucket, country HAVING ROUND((100 * SUM(CASE WHEN segment = 'Consumer' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 67 ORDER BY country, pct_consumer DESC, credit_limit_bucket LIMIT 10
